// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow issues; we only need enough ether
        amount = bound(amount, 10 ether, 100 ether);
        vm.deal(address(this), amount);
        // Record the state before the call
        uint256 prevPastBlockTime = c.pastBlockTime();
        uint256 currentTimestamp = block.timestamp;
        // Call fallback with exactly 10 ether to pass the require
        (bool success, ) = address(c).call{value: 10 ether}("");
        if (success) {
            // The rule: pastBlockTime should be block.timestamp + 1 (for reference)
            // But since block.timestamp might change, we check that it's > prevPastBlockTime
            // and that it's exactly currentTimestamp + 1 (the value set by reference)
            assertTrue(c.pastBlockTime() == currentTimestamp + 1, "pastBlockTime should be block.timestamp + 1");
        }
    }
}

